1	/**
2	 * How the mascot moves.
3	 *
4	 * It does not steer toward points. It picks a direction and goes that way, which
5	 * is what makes it read as a creature wandering rather than an app animating a
6	 * sprite between coordinates. Three things shape the motion:
7	 *
8	 * - a heading that turns at a limited rate toward whatever direction it was last
9	 *   asked to go, so a change of mind is a curve and not a corner;
10	 * - a slow sway layered onto the velocity, small enough to be felt rather than
11	 *   seen, which is the difference between "drifting" and "travelling in a
12	 *   straight line";
13	 * - the walls. The card grid is a wall, not a filter. The mascot slides along it
14	 *   the way anything moving through a room does, so it can never end up over a
15	 *   card without anything having to decide that it should not.
16	 *
17	 * Pure and frame-rate independent: `drift` takes seconds and returns a new state.
18	 * The store calls it once per frame from the mascot engine's own rAF, which is
19	 * already running, so continuous movement costs no additional loop.
20	 */
21	
22	import { DEMI_VIEWBOX, RAYON } from "./bot/repere";
23	
24	/** The one size the mascot is drawn at, in every slot and in the library. */
25	export const MASCOT_SIZE = 44;
26	
27	/**
28	 * What actually has to fit, which is the ink and not the drawing box. The engine
29	 * paints the body on a sphere of RAYON inside a viewBox of DEMI_VIEWBOX, and the
30	 * splash peaks a shade past the radius, so the blot covers about 63% of the box
31	 * it is drawn in. A little is added back for the idle drift. Measuring against
32	 * the box instead would refuse every lane this library actually has.
33	 */
34	const MASCOT_BODY = Math.ceil((2 * 1.06 * RAYON * MASCOT_SIZE) / (2 * DEMI_VIEWBOX) + 1);
35	
36	/**
37	 * How close the mascot's centre has to stay to a wall for its ink to miss it.
38	 * Every wall is inflated by this before the drift sees it, because a test on the
39	 * centre alone puts the ink straight over a card the moment the lane is narrower
40	 * than the mascot: the margins either side of a four column grid are about as
41	 * wide as the blot is wide, so the centre test passes and the blot does not.
42	 */
43	export const BODY_RADIUS = MASCOT_BODY / 2;
44	
45	export interface Vec {
46	  x: number;
47	  y: number;
48	}
49	
50	export interface Rect {
51	  left: number;
52	  top: number;
53	  right: number;
54	  bottom: number;
55	}
56	
57	/** Position and velocity. A velocity rather than a heading, so it can slide. */
58	export interface DriftState {
59	  x: number;
60	  y: number;
61	  vx: number;
62	  vy: number;
63	}
64	
65	/**
66	 * A amble. Slow enough to ignore, slow enough that the sway reads as drift
67	 * rather than as a wobble on a pass. Tuned down twice against a recording:
68	 * faster than this and the mascot stops feeling like it is ambling and starts
69	 * feeling like it is late for something.
70	 */
71	export const CRUISE_SPEED = 22;
72	
73	/** How fast it can change its mind, in radians per second. */
74	export const TURN_RATE = 0.55;
75	
76	/**
77	 * How far the sway pushes off the intended direction, in radians. About three and
78	 * a half degrees, which is felt rather than seen. This was 0.12, seven degrees,
79	 * and a recording of it walking a long pass showed the line weaving enough to
80	 * read as a designed swoop rather than something going somewhere.
81	 */
82	export const SWAY_AMPLITUDE = 0.06;
83	
84	/** The two rates the sway runs at. Incommensurate, so it never repeats. */
85	const SWAY_RATE_A = 0.37;
86	const SWAY_RATE_B = 0.23;
87	
88	/**
89	 * How far off its aim a wall has to push the mascot before the aim is
90	 * considered broken. A deflection is usually square, so this cannot be a test
91	 * for "facing the other way".
92	 */
93	const DEFLECTION_ANGLE = 1.2;
94	
95	/**
96	 * Below this fraction of its cruise the mascot has been stopped by something -
97	 * a wall it walked into head on, or a corner - and needs a fresh direction
98	 * rather than the one that walked it there.
