112	function shortestAngle(from: number, to: number): number {
113	  let delta = (to - from) % (Math.PI * 2);
114	  if (delta > Math.PI) delta -= Math.PI * 2;
115	  if (delta < -Math.PI) delta += Math.PI * 2;
116	  return delta;
