124	/**
125	 * The sway, as a perpendicular nudge. Driven by total elapsed time on two rates
126	 * that do not divide into each other, so no two outings trace the same line and
127	 * the mascot cannot learn a rhythm.
128	 */
129	function sway(elapsed: number, phase: number): number {
130	  return (
131	    Math.sin(elapsed * SWAY_RATE_A + phase) * 0.7 +
132	    Math.cos(elapsed * SWAY_RATE_B + phase * 1.7) * 0.3
133	  );
134	}
