136	/**
137	 * One frame.
138	 *
139	 * `aim` is the direction it was last told to head in, or null to carry on in
140	 * whatever direction it is already going. `cruise` scales the pace for this leg,
141	 * so consecutive legs differ without the speed ever jumping.
142	 */
143	export function drift(
144	  state: DriftState,
145	  terrain: Terrain,
146	  seconds: number,
147	  elapsed: number,
148	  aim: number | null,
149	  cruise = CRUISE_SPEED,
150	  phase = 0,
151	): DriftState {
152	  const step = Math.min(seconds, 0.05);
153	
154	  let speed = Math.hypot(state.vx, state.vy);
155	  let heading = speed > 0.001 ? Math.atan2(state.vy, state.vx) : (aim ?? 0);
156	
157	  if (aim !== null) {
158	    // Turn toward the aim at a limited rate. A change of mind is a curve.
159	    const turn = clamp(shortestAngle(heading, aim), -TURN_RATE * step, TURN_RATE * step);
160	    heading += turn;
161	  }
162	  // Ease the pace rather than snapping to it, so a leg never starts with a lurch.
163	  const wanted = cruise * (0.55 + 0.45 * Math.min(1, speed / Math.max(1, cruise)));
164	  speed += clamp(wanted - speed, -cruise * 1.6 * step, cruise * 1.6 * step);
165	
166	  // The sway, perpendicular to travel, so it never fights the aim.
167	  heading += sway(elapsed, phase) * SWAY_AMPLITUDE * step * 12;
168	
169	  let x = state.x + Math.cos(heading) * speed * step;
170	  let y = state.y + Math.sin(heading) * speed * step;
171	  let vx = Math.cos(heading) * speed;
172	  let vy = Math.sin(heading) * speed;
173	
174	  // The room. Reflect the normal component, which is a slide, not a stop.
175	  const pad = 6;
176	  if (x < terrain.room.left + pad) {
177	    x = terrain.room.left + pad;
178	    vx = Math.abs(vx);
179	  }
180	  if (x > terrain.room.right - pad) {
181	    x = terrain.room.right - pad;
182	    vx = -Math.abs(vx);
183	  }
184	  if (y < terrain.room.top + pad) {
185	    y = terrain.room.top + pad;
186	    vy = Math.abs(vy);
187	  }
188	  if (y > terrain.room.bottom - pad) {
189	    y = terrain.room.bottom - pad;
190	    vy = -Math.abs(vy);
191	  }
192	
193	  // The walls, which at the moment is the card grid. Steps are a fraction of a
194	  // pixel at this pace, so nothing can tunnel through one.
195	  //
196	  // The normal component is removed rather than reversed. Reversing is a bounce,
197	  // and a mascot that bounces off the grid and heads straight back into it
198	  // oscillates against the cards for the rest of the leg; taking the tangent and
199	  // carrying on is a slide, which is what anything moving through a room does.
200	  for (const wall of terrain.walls) {
201	    if (x <= wall.left || x >= wall.right || y <= wall.top || y >= wall.bottom) continue;
202	    const outLeft = x - wall.left;
203	    const outRight = wall.right - x;
204	    const outTop = y - wall.top;
205	    const outBottom = wall.bottom - y;
206	    const least = Math.min(outLeft, outRight, outTop, outBottom);
207	    if (least === outLeft) {
208	      x = wall.left;
209	      vx = 0;
210	    } else if (least === outRight) {
211	      x = wall.right;
212	      vx = 0;
213	    } else if (least === outTop) {
214	      y = wall.top;
215	      vy = 0;
216	    } else {
217	      y = wall.bottom;
218	      vy = 0;
219	    }
220	  }
221	
222	  return { x, y, vx, vy };
223	}
224	
225	/** Current speed, for the dev readout. */
226	export function speedOf(state: DriftState): number {
227	  return Math.hypot(state.vx, state.vy);
228	}
229	
230	/** The direction it is currently heading, for the dev board. */
231	export function headingOf(state: DriftState): number {
232	  return Math.atan2(state.vy, state.vx);
233	}
234	
235	/**
236	 * The heading to adopt after a wall has pushed the mascot off course.
237	 *
238	 * A wall removes the normal component of the velocity and leaves the tangential
239	 * one, so the mascot is not stopped - but the aim still points into the wall, the
240	 * next frame steers it back in, and it spends the rest of the leg grinding along
241	 * the grid. Taking the deflected direction as the new aim is what turns that into
242	 * actually going somewhere.
243	 *
244	 * The test is the angle between them and not whether they face opposite ways: a
245	 * deflection usually leaves the mascot travelling at ninety degrees to where it
246	 * was aimed, which is exactly opposite of "still on course" but is not more than
247	 * zero degrees of disagreement either.
248	 */
249	export function deflectedAim(aim: number | null, state: DriftState): number | null {
250	  if (aim === null || speedOf(state) <= 1) return aim;
251	  return Math.abs(shortestAngle(headingOf(state), aim)) > DEFLECTION_ANGLE ? headingOf(state) : aim;
252	}
